update bootcamp_private.challenge_catalog c
set data=c.data||jsonb_build_object('hint',revised.hint,'difficulty','Schwer')
from (values
 ('run', '20 Minuten locker joggen oder zügig gehen', 'Mache zwei Ausdauereinheiten an verschiedenen Tagen. Jogge je 30 Minuten locker oder gehe je 45 Minuten zügig.'),
 ('stairs', '10 Minuten Treppensteigen oder bergauf gehen', 'Sammle an zwei Tagen je 20 Minuten Treppensteigen oder bergauf gehen. Plane Pausen ein.'),
 ('walk', 'Gehe 30 Minuten auf einer neuen Route spazieren', 'Erkunde zwei neue Routen von jeweils mindestens vier Kilometern zu Fuß.'),
 ('cycle', 'Fahre 20 Minuten mit dem Rad', 'Fahre insgesamt 90 Minuten Rad, auf mindestens zwei Fahrten verteilt.'),
 ('dance', 'Tanze zu drei Songs deiner Wahl', 'Tanze an zwei Tagen je 20 Minuten. Stell dir dafür eine Playlist zusammen.'),
 ('balance', 'Stehe je Seite zweimal 30 Sekunden auf einem Bein', 'Trainiere an drei Tagen je zehn Minuten Gleichgewicht. Wechsel zwischen Einbeinstand, Fersen-Zehen-Gang und langsamen Schrittwechseln.'),
 ('mobility', 'Mache 10 Minuten lockere Mobilitätsübungen', 'Mache an drei Tagen je 20 Minuten Mobilität für Hüfte, Schultern und Rücken.'),
 ('deck', 'Würfle dreimal und mache jeweils so viele Kniebeugen', 'Würfle sechs Runden. Jede Runde besteht aus 6 plus Augenzahl Kniebeugen und 20 Sekunden Plank. Mach dazwischen Pause.'),
 ('friend', 'Verabrede dich zu einem Spaziergang oder einer kurzen Trainingseinheit', 'Trainiere zweimal je 30 Minuten mit einer anderen Person. Spaziergang in zügigem Tempo oder gemeinsames Workout zählen.'),
 ('pool-0-0', 'Gehe 25 Minuten zügig spazieren.', 'Gehe an drei Morgen jeweils 30 Minuten zügig spazieren.'),
 ('pool-0-1', 'Wechsle fünfmal zwischen zwei Minuten Gehen und einer Minute lockerem Joggen.', 'Mach an zwei Tagen sechs Intervalle aus zwei Minuten lockerem Joggen und zwei Minuten Gehen. Wärm dich vorher auf.'),
 ('pool-0-2', 'Sammle an einem Tag 7.000 Schritte.', 'Sammle an drei Tagen jeweils 8.000 Schritte.'),
 ('pool-0-3', 'Gehe oder jogge eine Runde durch einen Park. Plane 25 Minuten ein.', 'Gehe oder jogge an zwei Tagen jeweils 40 Minuten durch einen Park.'),
 ('pool-0-4', 'Mache drei Sätze mit je zwölf Kniebeugen.', 'Mache an zwei Tagen vier Sätze mit je 15 Kniebeugen. Pause zwischen den Sätzen.'),
 ('pool-0-5', 'Mache drei Sätze mit je zwölf Liegestützen an einer Wand.', 'Mache an zwei Tagen vier Sätze mit je 15 Liegestützen an einer Wand oder stabilen erhöhten Fläche.'),
 ('pool-0-6', 'Sammle insgesamt 90 Sekunden im Wandsitz, auf mehrere Sätze verteilt.', 'Sammle vier Minuten Wandsitz über die Woche. Verteile sie auf mindestens zwei Tage und mehrere Sätze.'),
 ('pool-0-7', 'Halte pro Seite zweimal 20 Sekunden Seitstütz, bei Bedarf auf den Knien.', 'Sammle drei Minuten Seitstütz pro Seite über mindestens zwei Tage. Teile die Zeit in kurze Sätze auf.'),
 ('pool-0-8', 'Mache drei Sätze mit je zwölf Wiederholungen.', 'Mache an zwei Tagen vier Sätze mit je 15 Wiederholungen Beckenheben.'),
 ('pool-0-9', 'Mache dreimal 15 Wiederholungen, bei Bedarf mit Halt.', 'Mache an zwei Tagen vier Sätze mit je 20 Wiederholungen Wadenheben, bei Bedarf mit Halt.'),
 ('pool-0-10', 'Mache zweimal acht Wiederholungen pro Seite.', 'Mache an zwei Tagen drei Sätze mit je zehn Rückwärts-Ausfallschritten pro Seite.'),
 ('pool-0-11', 'Schwimme 15 Minuten in lockerem Tempo. Alternativ gehe 20 Minuten spazieren.', 'Schwimme zweimal je 25 Minuten locker. Alternativ gehe zweimal je 40 Minuten zügig spazieren.'),
 ('pool-0-12', 'Geh in der Mittagspause 20 Minuten zügig nach draußen.', 'Geh an drei Mittagspausen jeweils 30 Minuten zügig nach draußen.'),
 ('pool-0-13', 'Mache zweimal je acht Bird Dogs pro Seite und 20 Sekunden Plank.', 'Mache an zwei Tagen drei Runden aus je zehn Bird Dogs pro Seite und 30 Sekunden Plank.'),
 ('pool-2-0', 'Versuche fünf langsame Kniebeugen mit einer Klopapierrolle auf dem Kopf.', 'Mache drei Sätze mit je zwölf langsamen Kniebeugen. Versuche im letzten Satz, eine Klopapierrolle auf dem Kopf zu balancieren.'),
 ('pool-2-1', 'Finde unterwegs drei Dinge: ein rotes Fahrrad, einen Vogel und etwas Rundes.', 'Geh an zwei Tagen je 35 Minuten spazieren und finde insgesamt sechs verschiedene Dinge für dein Bingo-Feld.'),
 ('pool-2-2', 'Steh beim Zähneputzen je Seite kurz auf einem Bein. Halte dich bei Bedarf fest.', 'Mache an drei Tagen je drei 30-Sekunden-Einbein-Sätze pro Seite. Halte dich bei Bedarf fest.'),
 ('pool-2-3', 'Würfle viermal und mache pro Wurf so viele Wand-Liegestütze wie Augen gefallen sind.', 'Würfle sechs Runden. Pro Runde machst du die Augenzahl plus sechs erhöhte Liegestütze. Pausiere zwischen den Runden.'),
 ('pool-2-4', 'Mache in zwei Fernseh- oder Streamingpausen jeweils fünf Kniebeugen.', 'Mach in vier Pausen je 15 Kniebeugen und 30 Sekunden Plank. Verteile die Pausen auf zwei Tage.'),
 ('pool-2-5', 'Gehe 20 Minuten spazieren und erkunde dabei eine Grünfläche, die du selten besuchst.', 'Erkunde zwei Grünflächen zu Fuß. Plane je 40 Minuten ein und baue unterwegs jeweils drei zügige Abschnitte ein.'),
 ('pool-2-6', 'Wirf fünf Sockenpaare in einen Wäschekorb. Pro Fehlwurf machst du zwei Kniebeugen.', 'Wirf zehn Sockenpaare in den Korb. Mach nach jedem Wurf fünf Kniebeugen. Wiederhole die Runde an einem anderen Tag.'),
 ('pool-2-7', 'Bewege dich 30 Sekunden in möglichst dramatischer Lauf-Zeitlupe. Wiederhole es zweimal.', 'Mache an zwei Tagen sechs Runden aus je 30 Sekunden dramatischer Lauf-Zeitlupe und 30 Sekunden lockerem Marschieren.'),
 ('pool-2-8', 'Gehe dreimal 15 Sekunden im Bärengang oder marschiere auf der Stelle.', 'Mache an zwei Tagen sechs 20-Sekunden-Runden Bärengang oder zügiges Marschieren auf der Stelle.'),
 ('pool-2-9', 'Gehe 20 Minuten raus und fotografiere drei Dinge in derselben Farbe.', 'Geh zweimal je 40 Minuten spazieren und fotografiere auf jeder Runde vier Dinge in derselben Farbe.'),
 ('pool-2-10', 'Boxe dreimal je 30 Sekunden locker in die Luft, mit Pausen.', 'Boxe an zwei Tagen je acht Runden à 45 Sekunden locker in die Luft. Dazwischen je 30 Sekunden Pause.'),
 ('pool-2-11', 'Gehe gemütlich eine Treppe hoch und runter und schätze vorher die Stufenzahl. Wiederhole es dreimal.', 'Sammle an zwei Tagen je 15 Minuten Treppensteigen in ruhigem Tempo. Schätze vor jeder Runde die Stufenzahl.'),
 ('pool-2-12', 'Würfelt abwechselnd. Jede Person macht insgesamt zehn bis zwanzig Kniebeugen oder Wand-Liegestütze.', 'Würfelt zu zweit sechs Runden. Jede Person macht pro Runde sechs plus Augenzahl Kniebeugen oder erhöhte Liegestütze.')
) revised(id,old_hint,hint)
where c.kind='weekly' and c.id=revised.id and c.data->>'hint'=revised.old_hint;
